import{calculator,CalcError,num,pos,frac,nonneg,dflt,pick}from './core.js?ver=afdd9441fa';
export const generator_fuel=calculator((i,d)=>{const fuel=pick(i,'fuel',['petrol','diesel'],'petrol');const curve=d?.generator_fuel?.fuels?.[fuel];if(!(curve?.slope_l_per_kwh>0)||!(curve?.intercept_l_per_h_per_kw_rated>=0))throw new CalcError('fuel_data_missing','fuel');const kva=pos(i,'kva');const pf=frac(i,'pf',dflt(d,'pf_generator'));const rated_kw=kva*pf;const load_w=nonneg(i,'load_w');const load_kw=load_w/1000;if(load_kw>rated_kw+1e-9)throw new CalcError('load_above_generator','load_w');const hours=num(i,'hours',{def:1,min:0,max:24});const days=nonneg(i,'days',dflt(d,'days_per_month'));const price=nonneg(i,'price',d.generator_fuel.prices?.[fuel]?.rs_per_litre);const l_per_h=curve.intercept_l_per_h_per_kw_rated*rated_kw+curve.slope_l_per_kwh*load_kw;const out={fuel,kva,pf,rated_kw,load_w,load_kw,load_pct:(load_kw/rated_kw)*100,hours,days,price,intercept:curve.intercept_l_per_h_per_kw_rated,slope:curve.slope_l_per_kwh,idle_l_per_h:curve.intercept_l_per_h_per_kw_rated*rated_kw,l_per_h,l_per_day:l_per_h*hours,l_per_month:l_per_h*hours*days,rs_per_h:l_per_h*price,rs_per_day:l_per_h*hours*price,rs_per_month:l_per_h*hours*days*price,};if(load_kw>0)Object.assign(out,{l_per_kwh:l_per_h/load_kw,rs_per_unit:(l_per_h*price)/load_kw});return out;});
